std::vector<Player*> Grid::nearby(const Player& p, float radius) {
  std::vector<Player*> result;
  int cx = (int)(p.x / CELL_SIZE), cy = (int)(p.y / CELL_SIZE);
  for (int dx = -1; dx <= 1; dx++)
    for (int dy = -1; dy <= 1; dy++) {
      int x = cx + dx, y = cy + dy;
      if (x < 0 || y < 0 || x >= NUM_CELLS || y >= NUM_CELLS) continue;
      for (Player* o : cells_[x][y])
        if (o != &p && distance(p, *o) < radius) result.push_back(o);
    }
  return result;
}

void Grid::handleCell(int x, int y) {
  Unit* unit = cells_[x][y];
  while (unit != NULL) {
    // Pairs in this cell (each pair once).
    handleUnit(unit, unit->next_);
    // Half of the neighbors to avoid double hits.
    if (x > 0 && y > 0) handleUnit(unit, cells_[x - 1][y - 1]);
    if (x > 0) handleUnit(unit, cells_[x - 1][y]);
    if (y > 0) handleUnit(unit, cells_[x][y - 1]);
    if (x > 0 && y < NUM_CELLS - 1)
      handleUnit(unit, cells_[x - 1][y + 1]);
    unit = unit->next_;
  }
}

class World {
public:
  Ship* spawnShip(double x, double y) {
    ships_.push_back(new Ship(x, y));
    grid_.add(ships_.back());       // keep both in sync
    return ships_.back();
  }
  void destroyShip(Ship* s) {
    grid_.remove(s);
    ships_.erase(std::find(ships_.begin(), ships_.end(), s));
    delete s;
  }
  void update() {
    for (Ship* s : ships_) s->update();  // no empty cells walked
    grid_.handleCombat();
  }
private:
  std::vector<Ship*> ships_;
  Grid grid_;
};
